entries.query_sql:
DECLARE @StartDate DATE;
DECLARE @EndDate DATE;

SELECT @StartDate = CAST([ParameterValue] AS DATE)
FROM [core].[GlobalParameters] 
WHERE [ParameterKey] = 'CUSTORDER_START';

SELECT @EndDate = CAST([ParameterValue] AS DATE)
FROM [core].[GlobalParameters] 
WHERE [ParameterKey] = 'CUSTORDER_END';

SELECT *
FROM [datavault].[SAT_CUSTORDER]
WHERE ORDER_DATE BETWEEN @StartDate AND @EndDate;

IF OBJECT_ID('[stage].[S_TEST]', 'U') IS NOT NULL
    DROP TABLE [stage].[S_TEST];

SELECT * INTO [stage].[S_TEST]
FROM (
SELECT 1 AS TEST
) AS source_query;
